FILE: app/src/hover.ts
```ts
import { createAnimationTask, addAnimationTask } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function startHover(manager: AnimationManager, node: { position: { y: number } }): (strength: number) => void {
    const rest = node.position.y;
    let strength = 1;
    let elapsed = 0;

    const task = createAnimationTask((_mgr, deltaMs) => {
        elapsed += deltaMs / 1000;
        const t = elapsed % 1;
        node.position.y = rest + strength * 0.5 * (1 - Math.abs(2 * t - 1));
    });

    addAnimationTask(manager, task);

    return (s: number) => {
        strength = s;
    };
}
```

I created `src/hover.ts` which registers a custom `AnimationTask` on the manager that accumulates elapsed time each update and writes a linear triangle-wave offset (period 1 s, peak 0.5) scaled by a mutable strength captured in the closure; the returned setter only updates that strength so it takes effect on the next update without resetting the phase. I was not sure of anything — the API surface and the notes were sufficient to implement this without ambiguity.
